import {TOPICS,questionsFromCSV,selectNext,nextLevel,grade,sheetURL} from './engine.js';
import {QUESTIONS} from './questions.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem('cslab.'+k))??f;}catch{return f;}};
function save(k,v){try{localStorage.setItem('cslab.'+k,JSON.stringify(v));return true;}catch{toast('Браузер не разрешил сохранение. Данные останутся только в этой сессии.');return false;}}
let bank=read('bank',null),history=read('history',[]),name=read('name',''),source=read('source',''),session=null,timer=null,lastResult=null,setupTopic='all';
try{if(bank)bank=questionsFromCSV(toCSV(bank));}catch{bank=null;source='';}
if(!Array.isArray(history))history=[];
function toCSV(questions){const rows=[['id','topic','difficulty','question','a','b','c','d','correct','explanation','code'],...questions.map(q=>[q.id,q.topic,q.difficulty,q.question,...q.options,q.correct+1,q.explanation,q.code])];return '\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');}
function pool(){return bank||QUESTIONS;}function topicName(id){return TOPICS.find(t=>t.id===id)?.name||'Все темы';}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.id);toast.id=setTimeout(()=>$('#toast').classList.remove('visible'),5500);}
function download(text,filename,type='text/csv;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function stats(){const answered=history.reduce((n,h)=>n+h.answers.length,0),correct=history.reduce((n,h)=>n+h.answers.filter(a=>a.correct).length,0);return [{label:'Пройдено тестов',value:history.length,sub:history.length?'Хороший темп. Продолжай!':'Первая попытка — начало пути',icon:'▤'},{label:'Средний результат',value:answered?Math.round(correct/answered*100)+'%':'—',sub:'По всем ответам в истории',icon:'↗'},{label:'Вопросов в базе',value:pool().length,sub:bank?'Из подключённой таблицы':'Проверенная база по C#',icon:'{ }'},{label:'Тем изучено',value:new Set(history.flatMap(h=>h.answers.map(a=>a.question.topic))).size+' / 6',sub:'Практика в каждой теме',icon:'◇'}];}
function cards(){return TOPICS.map(t=>{const count=pool().filter(q=>q.topic===t.id).length;const attempts=history.flatMap(h=>h.answers).filter(a=>a.question.topic===t.id);return `<button class="topic" data-start="${t.id}" ${!count?'disabled':''}><div class="topic-top"><span class="topic-icon ${t.color}">${esc(t.icon)}</span><span class="topic-count">${count} вопросов</span></div><h3>${t.name}</h3><p>${t.desc}</p><div class="topic-bottom"><span>${attempts.length?Math.round(attempts.filter(a=>a.correct).length/attempts.length*100)+'% верных ответов':'Начни с первого вопроса'}</span><span class="arrow">↗</span></div></button>`;}).join('');}
function home(){return `<div class="greeting"><div><h1>${name?'С возвращением, '+esc(name)+'!':'Твой следующий уровень — здесь.'} <span style="color:var(--lime)">✦</span></h1><p class="muted">Немного практики сегодня. Уверенный код завтра.</p></div><span class="tag">&lt; hello, developer /&gt;</span></div><section class="hero"><div class="hero-content"><span class="eyebrow">ПИШИ. ДУМАЙ. РАЗВИВАЙСЯ.</span><h2>Не просто знай C#.<br>Понимай, как он работает.</h2><p>Проверь себя на реальных примерах кода.<br>От первых переменных до асинхронности.</p><button class="btn dark" data-start="all">Начать тренировку <span>↗</span></button></div><div class="hero-art" aria-hidden="true"><div class="code-tile">C#</div><div class="spark">✧</div></div></section><section class="stats" aria-label="Твоя статистика">${stats().map(s=>`<div class="stat"><div class="stat-top">${s.label}<span class="stat-icon">${s.icon}</span></div><strong>${s.value}</strong><small>${s.sub}</small></div>`).join('')}</section><div class="section-head"><div><h2>Что будем прокачивать?</h2><p class="muted">Выбери тему или доверься адаптивной тренировке.</p></div><a class="text-link no-wrap" href="#topics">Все темы →</a></div><section class="topic-grid">${cards()}</section><section class="bottom-banner"><span class="banner-icon">⇄</span><div><h3>Тренировка, которая подстраивается под тебя</h3><p>Верный ответ — задача сложнее. Ошибка — шаг назад и понятное объяснение.</p></div><button class="text-link" data-adaptive>Попробовать →</button></section>`;}
function historyPage(){return `<h1 class="page-heading">Мой прогресс</h1><p class="page-intro">Каждая попытка — ещё один шаг вперёд. История хранится в этом браузере.</p>${history.length?`<div class="inline-actions" style="margin-bottom:20px"><button class="btn" data-export-history>Экспорт истории · JSON ↓</button><button class="text-link" data-clear>Очистить историю</button></div><div class="panel">${history.map((h,i)=>`<div class="history-item"><div class="score-pill">${h.percent}%</div><div><h3>${esc(h.name||'Студент')} · ${esc(topicName(h.topic))}</h3><p>${new Date(h.date).toLocaleString('ru-RU')} · ${modeName(h.mode)} · ${h.answers.filter(a=>a.correct).length}/${h.answers.length} верно</p></div><button class="btn" data-review="${i}">Разбор ↗</button></div>`).join('')}</div>`:`<div class="panel empty"><div class="empty-icon">↗</div><h2>У каждой истории есть начало</h2><p class="muted">Пройди первый тест — здесь появятся твои результаты.</p><button class="btn primary" data-start="all">Начать тренировку →</button></div>`}`;}
function sourcePage(){return `<h1 class="page-heading">Вопросы из Google Таблиц</h1><p class="page-intro">Преподаватель редактирует таблицу — ты загружаешь обновлённую базу одним нажатием.</p><div class="panel source-panel"><div class="source-status">● ${bank?'Подключена своя база':'Используется встроенная база'} · ${pool().length} вопросов</div><h2>Подключить таблицу</h2><ol class="steps"><li>Скачай CSV-шаблон и импортируй его в Google Таблицы.</li><li>Выбери «Файл → Поделиться → Опубликовать в интернете».</li><li>Выбери нужный лист, формат CSV и скопируй ссылку ниже.</li></ol><form id="source-form"><label>Ссылка на опубликованную Google Таблицу<input type="url" id="sheet-url" placeholder="https://docs.google.com/spreadsheets/d/e/…/pub?output=csv" value="${esc(source)}" required></label><p class="small muted">Также поддерживается ссылка на таблицу с доступом «Все, у кого есть ссылка».</p><div class="inline-actions"><button type="submit" class="btn primary" id="sync-btn">Загрузить вопросы ↻</button><button type="button" class="btn" data-template>CSV-шаблон ↓</button><button type="button" class="btn" data-import>Импорт CSV-файла ↑</button></div><p id="source-error" class="error-text" role="alert"></p></form><input type="file" accept=".csv,text/csv" id="csv-file" hidden><div class="notice">Загружаются только публичные данные. Не добавляй в таблицу персональные данные и секреты. В этой версии ответы доступны в браузере: это тренажёр, а не защищённая система аттестации. Обновление выполняется кнопкой; загруженная копия сохраняется в этом браузере.</div>${bank?'<button class="text-link" data-reset-source>Вернуться к встроенной базе →</button>':''}</div><div class="panel"><h2>Формат таблицы</h2><p class="muted small"><code>id, topic, difficulty, question, a, b, c, d, correct, explanation, code</code></p><p class="muted small">Темы: ${TOPICS.map(t=>'<code>'+t.id+'</code>').join(', ')}.<br>Сложность: 1–3. Правильный ответ: 1–4. Поле code необязательное. Все ID должны быть уникальными. При ошибке старая база сохранится.</p></div>`;}
function modeName(mode){return {practice:'Тренировка',adaptive:'Адаптивный режим',exam:'Экзамен'}[mode];}
function render(){if(session)return;const page=location.hash.slice(1)||'home';const pages={home,topics:()=>`<h1 class="page-heading">Темы и тесты</h1><p class="page-intro">Шесть направлений. Три уровня сложности. Выбирай, с чего начнём.</p><div class="inline-actions" style="margin-bottom:25px"><button class="btn primary" data-start="all">Смешанный тест ↗</button><button class="btn" data-adaptive>Адаптивная тренировка ⇄</button></div><section class="topic-grid">${cards()}</section>`,history:historyPage,source:sourcePage};$('#app').innerHTML=(pages[page]||home)();$('#page-title').textContent={home:'Обзор',topics:'Темы и тесты',history:'Мой прогресс',source:'Источник вопросов'}[page]||'Обзор';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));$('#source-badge').textContent=bank?'Google / CSV · '+pool().length:'Встроенная база';}
function openSetup(topic='all',mode='practice'){setupTopic=topic;$('#setup-title').textContent=topic==='all'?'Новая тренировка':topicName(topic);$('#student-name').value=name;$('#mode').value=mode;const n=pool().filter(q=>topic==='all'||q.topic===topic).length;$('#pool-note').textContent=`Доступно ${n} вопросов. Если их меньше выбранного количества, используем все.`;$('#setup').showModal();}
$('#close-setup').onclick=()=>$('#setup').close();
$('#setup-form').onsubmit=e=>{e.preventDefault();name=$('#student-name').value.trim();save('name',name);const candidates=pool().filter(q=>setupTopic==='all'||q.topic===setupTopic);if(!candidates.length)return;const mode=$('#mode').value;session={topic:setupTopic,mode,candidates,total:Math.min(Number($('#count').value),candidates.length),answers:[],level:1,chosen:null,locked:false,start:Date.now(),deadline:Date.now()+15*60*1000};$('#setup').close();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.remove('active'));$('#page-title').textContent=modeName(mode);nextQuestion();if(mode==='exam')timer=setInterval(tick,1000);window.scrollTo(0,0);};
function nextQuestion(){session.current=selectNext(session.candidates,session.answers.map(a=>a.question.id),session.mode==='adaptive'?session.level:Math.ceil(Math.random()*3));session.chosen=null;session.locked=false;renderQuiz();}
function renderQuiz(){const s=session,q=s.current;$('#app').innerHTML=`<div class="quiz-wrap"><div class="quiz-top"><button class="text-link" data-exit>← Завершить сессию</button><span class="tag">${modeName(s.mode)}</span>${s.mode==='exam'?'<span class="timer" id="timer" aria-label="Осталось времени">15:00</span>':''}</div><div class="section-head"><span class="muted small">Вопрос ${s.answers.length+1} из ${s.total}</span><span class="small">${Math.round(s.answers.length/s.total*100)}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${s.answers.length/s.total*100}%"></div></div><div class="panel"><span class="question-label">${esc(topicName(q.topic))} · УРОВЕНЬ ${q.difficulty} / 3</span><h1 class="question-title">${esc(q.question)}</h1>${q.code?`<pre><code>${esc(q.code)}</code></pre>`:''}<div class="answers" role="group" aria-label="Варианты ответа">${q.options.map((o,i)=>`<button class="answer" data-answer="${i}" aria-pressed="false"><span class="answer-letter">${'ABCD'[i]}</span><span>${esc(o)}</span></button>`).join('')}</div><div id="feedback" aria-live="polite"></div><div class="quiz-actions"><span class="small muted">${s.mode==='exam'?'Ответы и разбор — после завершения':'Выбери один правильный ответ'}</span><button class="btn primary" id="submit-answer" disabled>Ответить →</button></div></div><p class="muted small">${s.mode==='adaptive'?'⇄ Начинаем с первого уровня. После верного ответа сложность повышается, после ошибки — снижается.':'Подсказка: внимательно прочитай код и все варианты ответа.'}</p></div>`;if(s.mode==='exam')tick();}
function choose(i){if(!session||session.locked)return;session.chosen=i;document.querySelectorAll('[data-answer]').forEach(b=>{const selected=Number(b.dataset.answer)===i;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected);});$('#submit-answer').disabled=false;}
function submit(){const s=session;if(!s)return;if(s.locked){if(s.answers.length>=s.total)finish();else nextQuestion();return;}if(s.chosen===null)return;const q=s.current,correct=s.chosen===q.correct;s.answers.push({question:q,chosen:s.chosen,correct});if(s.mode==='adaptive')s.level=nextLevel(s.level,correct);s.locked=true;if(s.mode==='exam'){if(s.answers.length>=s.total)finish();else nextQuestion();return;}document.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;const i=Number(b.dataset.answer);b.classList.toggle('correct',i===q.correct);b.classList.toggle('wrong',i===s.chosen&&!correct);});$('#feedback').innerHTML=`<div class="feedback ${correct?'':'bad'}"><strong>${correct?'Верно. Отличная работа!':'Есть над чем поработать.'}</strong><br>${esc(q.explanation)}</div>`;$('#submit-answer').textContent=s.answers.length>=s.total?'Посмотреть результат →':'Следующий вопрос →';}
function tick(){if(!session)return;const seconds=Math.max(0,Math.ceil((session.deadline-Date.now())/1000));if($('#timer'))$('#timer').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');if(seconds===0){toast('Время истекло. Результат сохранён.');finish();}}
function finish(){if(!session)return;clearInterval(timer);const s=session;const answers=[...s.answers];if(s.chosen!==null&&!s.locked)answers.push({question:s.current,chosen:s.chosen,correct:s.chosen===s.current.correct});const result={id:crypto.randomUUID(),date:new Date().toISOString(),name,topic:s.topic,mode:s.mode,total:s.total,duration:Math.round((Date.now()-s.start)/1000),answers,percent:Math.round(answers.filter(a=>a.correct).length/s.total*100)};history.unshift(result);history=history.slice(0,100);save('history',history);session=null;lastResult=result;renderResult(result);window.scrollTo(0,0);}
function renderResult(r){lastResult=r;$('#page-title').textContent='Результат сессии';const correct=r.answers.filter(a=>a.correct).length;$('#app').innerHTML=`<div class="quiz-wrap"><section class="panel result-hero"><span class="eyebrow">ЕЩЁ ОДИН ШАГ ВПЕРЁД</span><div class="result-number">${r.percent}%</div><h1>${r.percent>=85?'Отличная работа!':r.percent>=65?'Уверенный результат!':'Практика делает сильнее.'}</h1><p>${esc(r.name||'Студент')} · ${esc(topicName(r.topic))}<br>${correct} из ${r.total} верно · Оценка ${grade(r.percent)} · ${Math.floor(r.duration/60)} мин ${r.duration%60} сек</p><div class="result-buttons"><button class="btn primary" data-start="${r.topic}">Попробовать ещё ↗</button><button class="btn" data-download-result>Скачать результат ↓</button><a class="btn" href="#history" data-go-history>Мой прогресс</a></div><span class="small muted">Шкала: 85–100% → 5 · 65–84% → 4 · 45–64% → 3 · ниже 45% → 2</span></section><section class="panel"><h2>Разбор ответов</h2>${r.answers.map((a,i)=>`<article class="review"><h3><span class="${a.correct?'good-text':'bad-text'}">${a.correct?'✓':'×'}</span> ${i+1}. ${esc(a.question.question)}</h3>${a.question.code?`<pre><code>${esc(a.question.code)}</code></pre>`:''}<div class="${a.correct?'good-text':'bad-text'}">Твой ответ: ${esc(a.question.options[a.chosen])}</div>${a.correct?'':`<div class="good-text">Правильный: ${esc(a.question.options[a.question.correct])}</div>`}<p class="muted">${esc(a.question.explanation)}</p></article>`).join('')}${r.answers.length<r.total?`<p class="muted">Не отвечено: ${r.total-r.answers.length}. Эти вопросы учтены в общем количестве как неверные.</p>`:''}</section></div>`;}
async function loadSheet(e){e.preventDefault();const btn=$('#sync-btn'),error=$('#source-error');error.textContent='';btn.disabled=true;btn.textContent='Загрузка…';try{const url=sheetURL($('#sheet-url').value.trim());const res=await fetch(url,{signal:AbortSignal.timeout(15000),credentials:'omit'});if(!res.ok)throw Error('Google вернул ошибку '+res.status+'. Проверьте публикацию и доступ к таблице.');const text=await res.text();if(text.length>4_000_000)throw Error('Файл слишком большой: максимум 4 МБ.');const data=questionsFromCSV(text);bank=data;source=$('#sheet-url').value.trim();save('bank',bank);save('source',source);render();toast('База обновлена: '+data.length+' вопросов');}catch(err){error.textContent=err.name==='TimeoutError'?'Google не ответил за 15 секунд. Повторите загрузку или импортируйте CSV-файл.':err.message==='Failed to fetch'?'Не удалось загрузить таблицу. Проверьте публикацию или используйте импорт CSV-файла.':err.message;}finally{if(btn.isConnected){btn.disabled=false;btn.textContent='Загрузить вопросы ↻';}}}
$('#profile').onclick=()=>{if(session){toast('Имя можно изменить перед следующей сессией.');return;}openSetup();};
$('#app').addEventListener('submit',e=>{if(e.target.id==='source-form')loadSheet(e);});
$('#app').addEventListener('change',async e=>{if(e.target.id==='csv-file'&&e.target.files[0]){try{const file=e.target.files[0];if(file.size>4_000_000)throw Error('Максимальный размер файла — 4 МБ.');const data=questionsFromCSV(await file.text());bank=data;source='';save('bank',bank);save('source',source);render();toast('Импортировано '+data.length+' вопросов');}catch(err){$('#source-error').textContent=err.message;}e.target.value='';}});
$('#app').addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.hasAttribute('data-start'))openSetup(b.dataset.start);else if(b.hasAttribute('data-adaptive'))openSetup('all','adaptive');else if(b.hasAttribute('data-answer'))choose(Number(b.dataset.answer));else if(b.id==='submit-answer')submit();else if(b.hasAttribute('data-exit')){if(confirm('Завершить сессию? Неотвеченные вопросы будут учтены как неверные.'))finish();}else if(b.hasAttribute('data-template'))download(toCSV(QUESTIONS),'csharp-questions-template.csv');else if(b.hasAttribute('data-import'))$('#csv-file').click();else if(b.hasAttribute('data-reset-source')){bank=null;source='';save('bank',null);save('source','');render();toast('Восстановлена встроенная база');}else if(b.hasAttribute('data-review')){renderResult(history[Number(b.dataset.review)]);window.scrollTo(0,0);}else if(b.hasAttribute('data-go-history')){render();}else if(b.hasAttribute('data-clear')){if(confirm('Удалить всю историю попыток в этом браузере?')){history=[];save('history',history);render();}}else if(b.hasAttribute('data-export-history'))download(JSON.stringify(history,null,2),'csharp-history.json','application/json');else if(b.hasAttribute('data-download-result')){const r=lastResult;download(`C# LAB — РЕЗУЛЬТАТ\nИмя: ${r.name||'Студент'}\nТема: ${topicName(r.topic)}\nРежим: ${modeName(r.mode)}\nДата: ${new Date(r.date).toLocaleString('ru-RU')}\nРезультат: ${r.percent}%\nОценка: ${grade(r.percent)}\nВерно: ${r.answers.filter(a=>a.correct).length} из ${r.total}\nВремя: ${r.duration} сек.\n\nРАЗБОР\n`+r.answers.map((a,i)=>`${i+1}. ${a.question.question}\nОтвет: ${a.question.options[a.chosen]}\nПравильный: ${a.question.options[a.question.correct]}\n${a.question.explanation}`).join('\n\n'),'csharp-result.txt','text/plain;charset=utf-8');}});
window.addEventListener('hashchange',()=>{if(session)return;render();window.scrollTo(0,0);});
// Keep in-progress exams safe from silent navigation and refresh.
document.querySelector('nav').addEventListener('click',e=>{if(session){e.preventDefault();toast('Сначала завершите текущую сессию.');}});
window.addEventListener('beforeunload',e=>{if(session){e.preventDefault();e.returnValue='';}});render();
